mapper.select:
SELECT e.id, e.supplier_id, s.name AS supplier_name, s.short_name AS supplier_short_name, e.template_id, e.evaluate_json, e.serial_number, e.evaluate_date, e.score, e.score_rating, e.classify_id, e.column_map_json, e.user_id, u.name AS evaluator_name, e.review_status, e.approve_record_id, e.reviewer_id, e.reviewer_name, e.review_time FROM scm_supplier_evaluate e LEFT JOIN scm_supplier s ON e.supplier_id = s.id LEFT JOIN sys_user u ON e.user_id = u.id WHERE 1 = 1
AND e.review_status = #{param.reviewStatus}
AND e.review_status = 2
AND (s.name LIKE CONCAT('%', #{param.supplierName}, '%') OR s.short_name LIKE CONCAT('%', #{param.supplierName}, '%'))
AND e.classify_id = #{param.classifyId}
AND YEAR(e.evaluate_date) = #{param.evaluateYear}
AND e.score_rating LIKE CONCAT('%', #{param.scoreRating}, '%')
ORDER BY e.review_time desc ,e.id desc
